use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut sorted_values = Vec::new();
    for (key, value) in input.as_array() {
        sorted_values.push((key, value));
    }

    sorted_values.sort_unstable_by(|a, b| {
        if a.0 == b.0 {
            a.1.cmp(&b.1)
        } else {
            a.0.cmp(&b.0)
        }
    });

    sorted_values.into_iter().map(|(key, value)| serde_json::Value::Number(value as f64)).collect()
}
